import matplotlib.pyplot as plt
import pandas as pd
import seaborn as sns

# 1. Load the CSV generated by your Java program
df = pd.read_csv("conflict_matrix.csv", index_col=0)

# 2. Set up the figure size and high resolution for printing
plt.figure(figsize=(11, 9), dpi=300)

# 3. Draw the Seaborn Heatmap
sns.heatmap(
    df,
    annot=True,
    fmt="d",
    cmap="YlOrRd",
    cbar_kws={"label": "Shared Student Overlap"},
    linewidths=0.5,
    linecolor="#cccccc",
    square=True,
    cbar=True,
)

# 4. Poster Styling
plt.title(
    "Primal Student Conflict Matrix Heatmap",
    fontsize=15,
    fontweight="bold",
    pad=15,
)
plt.xlabel("Exam ID", fontsize=12, fontweight="bold", labelpad=8)
plt.ylabel("Exam ID", fontsize=12, fontweight="bold", labelpad=8)
plt.xticks(rotation=0, fontsize=9)
plt.yticks(fontsize=9)

# 5. Save as a crisp image file for your poster layout
plt.tight_layout()
plt.savefig(
    "exam_conflict_heatmap.png", dpi=300, bbox_inches="tight", format="png"
)
print("Saved 'exam_conflict_heatmap.png' successfully!")
plt.show()